using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Tool implementations ---
var notebook = new ResearchNotebook();
var webSearcher = new WebSearcher();

AITool[] tools =
[
    AIFunctionFactory.Create(webSearcher.SearchAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
];

// --- Build the chat client (MEAI abstraction layer) ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Build the agent (Microsoft Agent Framework orchestration layer) ---
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = tools,
        },
    });

// --- Run the agent ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (powered by AI)      ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

string topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

List<ChatMessage> history =
[
    new(ChatRole.System, """
        You are a research assistant. When given a topic:
        1. Use the search tool to find relevant information (make 2-3 searches with different queries).
        2. Use the note-taking tool to record key findings as you go.
        3. After gathering enough information, retrieve all notes and produce a well-structured summary.

        Always cite the sources you found. Be thorough but concise.
        """),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
];

var runOptions = new ChatClientAgentRunOptions(
    new ChatOptions { MaxOutputTokens = 4096 });

var response = await agent.RunAsync(history, options: runOptions);

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("                 FINDINGS                  ");
Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine(response.Text);
Console.WriteLine("═══════════════════════════════════════════");

if (notebook.Count > 0)
{
    Console.WriteLine($"\n📝 {notebook.Count} note(s) were recorded during research.");
}

Console.WriteLine("\n✅ Research complete.");

// --- Helper ---
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrWhiteSpace(input)
        ? "recent advances in quantum computing 2025"
        : input;
}

// ──────────────────────────────────────────────────────────────
//  Tool classes
// ──────────────────────────────────────────────────────────────

/// <summary>
/// Provides web search capability using the DuckDuckGo Instant Answer API.
/// </summary>
sealed class WebSearcher
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Searches the web for information on a given query and returns a list of result snippets.")]
    public async Task<string> SearchAsync(
        [Description("The search query to look up on the web.")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetFromJsonAsync<DdgResponse>(url);

            var results = new List<string>();

            if (!string.IsNullOrWhiteSpace(json?.Abstract))
            {
                results.Add($"[{json.AbstractSource}] {json.Abstract}");
            }

            if (json?.RelatedTopics is not null)
            {
                foreach (var topic in json.RelatedTopics.Take(5))
                {
                    if (!string.IsNullOrWhiteSpace(topic.Text))
                    {
                        results.Add($"- {topic.Text}");
                    }
                }
            }

            if (results.Count == 0)
            {
                results.Add($"No detailed results found for \"{query}\". Try a more specific query.");
            }

            var output = string.Join("\n", results);
            Console.WriteLine($"  ✅ Found {results.Count} result(s).");
            return output;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"  ⚠️  Search failed: {ex.Message}");
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }
}

sealed class DdgResponse
{
    [JsonPropertyName("Abstract")]
    public string? Abstract { get; set; }

    [JsonPropertyName("AbstractSource")]
    public string? AbstractSource { get; set; }

    [JsonPropertyName("RelatedTopics")]
    public List<DdgTopic>? RelatedTopics { get; set; }
}

sealed class DdgTopic
{
    [JsonPropertyName("Text")]
    public string? Text { get; set; }

    [JsonPropertyName("FirstURL")]
    public string? FirstURL { get; set; }
}

/// <summary>
/// An in-memory notebook that the agent uses to record and retrieve research findings.
/// </summary>
sealed class ResearchNotebook
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;

    [Description("Adds a research note. Use this to record key findings, facts, or quotes during research.")]
    public string AddNote(
        [Description("The note content to save.")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved.");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieves all previously saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes recorded yet.";
        }

        var formatted = _notes.Select((n, i) => $"[{i + 1}] {n}");
        return string.Join("\n", formatted);
    }
}

