+    public int Count => _notes.Count;
+
+    [Description("Adds a research note. Use this to record key findings, facts, or quotes during research.")]
+    public string AddNote(
+        [Description("The note content to save.")] string note)
+    {
+        _notes.Add(note);
+        Console.WriteLine($"  📝 Note #{_notes.Count} saved.");
+        return $"Note #{_notes.Count} saved successfully.";
+    }
+
+    [Description("Retrieves all previously saved research notes.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+        {
+            return "No notes recorded yet.";
+        }
+
+        var formatted = _notes.Select((n, i) => $"[{i + 1}] {n}");
+        return string.Join("\n", formatted);
+    }
+}

